<template><sf-sheet :open="!!gate" contained :resizable="false" :title="gate&&gate.title" @input="$emit('close')"><template v-if="gate"><sf-badge v-if="gate.kind!=='usage'" :tone="gate.expired?'warning':'accent'">{{ gate.expired?'Premium expired':'SunnyFit Premium' }}</sf-badge><h3 v-if="gate.contentName" class="mvp-gate-content">{{ gate.contentName }}</h3><p class="mvp-gate-body">{{ gate.body }}</p><ul class="mvp-gate-benefits"><li v-for="benefit in gate.benefits" :key="benefit"><sf-icon name="check" :size="17"/>{{ benefit }}</li></ul><p class="mvp-gate-note">{{ gate.kind==='usage'?'Your conversation allowance is separate from your membership status.':'Your Free workouts remain available. You can review your benefits and usage together.' }}</p></template><template #footer><sf-button @click="$emit('continue')">{{ gate&&gate.kind==='usage'?'Membership & Usage':gate&&gate.expired?'Rejoin Premium':'Explore Premium' }}</sf-button><sf-button appearance="glass" class="mvp-gate-later" @click="$emit('close')">Not now</sf-button></template></sf-sheet></template>
<script>import {SfSheet,SfButton,SfBadge,SfIcon} from '@/design-system';export default{components:{SfSheet,SfButton,SfBadge,SfIcon},props:{gate:Object}}</script>
<style scoped>.mvp-gate-content{font-size:19px;line-height:27px;margin:17px 0 8px}.mvp-gate-body{font-size:14px;line-height:23px;margin:16px 0;color:var(--sf-text-secondary)}.mvp-gate-benefits{list-style:none;padding:0;display:grid;gap:12px;margin:20px 0}.mvp-gate-benefits li{display:flex;gap:9px;font-size:13px;line-height:21px}.mvp-gate-benefits .sf-icon{color:var(--sf-success);flex-shrink:0;margin-top:1px}.mvp-gate-note{font-size:12px;line-height:20px;color:var(--sf-text-secondary)}.mvp-gate-later{margin-top:10px}</style>
